def header(*, r, kind, current="", section=""):
    """current: the path of this page, so its entry carries aria-current.
    section: which top-level menu this page belongs under (visual marker only -
    aria-current="page" on a menu BUTTON would claim the button is the page)."""
    html = HEADER.format(r=r)
    if current:
        html = html.replace('href="%s%s"' % (r, current),
                            'href="%s%s" aria-current="page"' % (r, current), 1)
    if section:
        html = html.replace('data-menu="%s"' % section,
                            'data-menu="%s" data-section-current="true"' % section, 1)
    return html.replace("<span class=\"kind\"></span>",
                        "<span class=\"kind\">%s</span>" % kind)


def drawer(*, r, current=""):
    html = DRAWER.format(r=r)
    if current:
        html = html.replace('href="%s%s"' % (r, current),
                            'href="%s%s" aria-current="page"' % (r, current), 1)
    return html


def footer(*, r, current=""):
    html = FOOTER.format(r=r)
    if current:
        html = html.replace('href="%s%s"' % (r, current),
                            'href="%s%s" aria-current="page"' % (r, current), 1)
    return html


def pill(*, r):
    return PILL.format(r=r)


